#include <stdio.h>
#include <errno.h>
#include <math.h>

// Minimal OptionType enum as in the public API
enum OptionType {
    OPT_TYPE_FUNC,
    OPT_TYPE_BOOL,
    OPT_TYPE_STRING,
    OPT_TYPE_INT,
    OPT_TYPE_INT64,
    OPT_TYPE_FLOAT,
    OPT_TYPE_DOUBLE,
    OPT_TYPE_TIME,
};

#ifndef AVERROR
#define AVERROR(e) (-(e))
#endif
#ifndef AV_LOG_FATAL
#define AV_LOG_FATAL 8
#endif

// External (non-standard) functions used by parse_number
// Implemented in stubs.c
extern void   av_log(void *avcl, int level, const char *fmt, ...);
extern double av_strtod(const char *nptr, char **endptr);

// Target function extracted/adapted from fftools/cmdutils.c
int parse_number(const char *context, const char *numstr, enum OptionType type,
                 double min, double max, double *dst)
{
    char *tail;
    const char *error;
    double d = av_strtod(numstr, &tail);
    if (*tail)
        error = "Expected number for %s but found: %s\n";
    else if (d < min || d > max)
        error = "The value for %s was %s which is not within %f - %f\n";
    else if (type == OPT_TYPE_INT64 && (int64_t)d != d)
        error = "Expected int64 for %s but found %s\n";
    else if (type == OPT_TYPE_INT && (int)d != d)
        error = "Expected int for %s but found %s\n";
    else {
        *dst = d;
        return 0;
    }

    av_log(NULL, AV_LOG_FATAL, error, context, numstr, min, max);
    return AVERROR(EINVAL);
}

