#include "harness.c"

int main() {
    // Symbolic number string buffer
    char numstr[32];
    klee_make_symbolic(numstr, sizeof(numstr), "numstr");
    // Ensure it is null-terminated somewhere
    numstr[31] = '\0';

    // Symbolic type within valid enum range
    int itype;
    klee_make_symbolic(&itype, sizeof(itype), "type");
    klee_assume(itype >= OPT_TYPE_FUNC && itype <= OPT_TYPE_TIME);

    // Symbolic bounds
    double minv, maxv;
    klee_make_symbolic(&minv, sizeof(minv), "minv");
    klee_make_symbolic(&maxv, sizeof(maxv), "maxv");
    // Constrain min <= max, finite
    klee_assume(!isnan(minv));
    klee_assume(!isnan(maxv));
    klee_assume(minv <= maxv);

    double dst = 0.0;

    // Context string
    const char *ctx = "opt";

    (void)parse_number(ctx, numstr, (enum OptionType)itype, minv, maxv, &dst);
    return 0;
}

