// harness.c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdarg.h>
#include <stdint.h>

// Mirror the OptionType from public API (only used for field presence)
enum OptionType {
    OPT_TYPE_FUNC,
    OPT_TYPE_BOOL,
    OPT_TYPE_STRING,
    OPT_TYPE_INT,
    OPT_TYPE_INT64,
    OPT_TYPE_FLOAT,
    OPT_TYPE_DOUBLE,
    OPT_TYPE_TIME,
};

// Minimal OptionDef sufficient for show_help_options
typedef struct OptionDef {
    const char *name;
    enum OptionType type;
    int flags;
    const char *argname;
    const char *help;
} OptionDef;

// Define bits used by show_help_options
#ifndef OPT_FLAG_PERSTREAM
#define OPT_FLAG_PERSTREAM (1 << 13)
#endif
#ifndef OPT_FLAG_SPEC
#define OPT_FLAG_SPEC (1 << 9)
#endif

// Minimal safe versions of av_strlcpy/lcat/lcatf used by show_help_options
static size_t av_strlcpy(char *dst, const char *src, size_t size) {
    size_t srclen = src ? strlen(src) : 0;
    if (size) {
        size_t copy = srclen < (size - 1) ? srclen : (size - 1);
        if (src && copy)
            memcpy(dst, src, copy);
        dst[copy] = '\0';
    }
    return srclen;
}

static size_t av_strlcat(char *dst, const char *src, size_t size) {
    size_t dstlen = strlen(dst);
    if (dstlen >= size) return dstlen + (src ? strlen(src) : 0);
    return dstlen + av_strlcpy(dst + dstlen, src, size - dstlen);
}

static int av_strlcatf(char *dst, size_t size, const char *fmt, const char *arg) {
    size_t dstlen = strlen(dst);
    if (dstlen >= size) return (int)dstlen;
    int n = snprintf(dst + dstlen, size - dstlen, fmt, arg);
    return (int)(dstlen + (n > 0 ? n : 0));
}

// Target function extracted/adapted from fftools/cmdutils.c
void show_help_options(const OptionDef *options, const char *msg, int req_flags,
                       int rej_flags)
{
    const OptionDef *po;
    int first;

    first = 1;
    for (po = options; po->name; po++) {
        char buf[128];

        if (((po->flags & req_flags) != req_flags) ||
            (po->flags & rej_flags))
            continue;

        if (first) {
            printf("%s\n", msg ? msg : "");
            first = 0;
        }
        av_strlcpy(buf, po->name, sizeof(buf));

        if (po->flags & OPT_FLAG_PERSTREAM)
            av_strlcat(buf, "[:<stream_spec>]", sizeof(buf));
        else if (po->flags & OPT_FLAG_SPEC)
            av_strlcat(buf, "[:<spec>]", sizeof(buf));

        if (po->argname)
            av_strlcatf(buf, sizeof(buf), " <%s>", po->argname);

        printf("-%-17s  %s\n", buf, po->help ? po->help : "");
    }
    printf("\n");
}

