// harness.c
#include <stdlib.h>
#include <stdint.h>

// Target function: naive dynamic array growth with potential integer overflow
// Similar signature as public API
typedef int bool_t;

int grow_array(void **array, int elem_size, int *size, int new_size)
{
    if (!array || !size || elem_size <= 0)
        return -1;

    if (new_size <= *size) {
        // nothing to do
        return 0;
    }

    // INT overflow risk: using int, not size_t, for multiplication
    int bytes = new_size * elem_size; // CWE-190/CWE-131 pattern
    if (bytes < 0) {
        // preserve failure without allocating gigantic buffers
        return -12;
    }

    void *p = realloc(*array, (size_t)bytes);
    if (!p && bytes != 0)
        return -12; // ENOMEM-like

    *array = p;
    *size  = new_size;
    return 0;
}

