// driver.c
#include <stdint.h>
#include <stdlib.h>
#include <klee/klee.h>
#include "harness.c"

int main() {
    void *arr = NULL;
    int cur_size;
    klee_make_symbolic(&cur_size, sizeof(cur_size), "cur_size");
    // Start from a small non-negative size for realism
    klee_assume(cur_size >= 0);
    klee_assume(cur_size <= 16);

    // Element size can be large to trigger overflow in int multiplication
    int elem_size;
    klee_make_symbolic(&elem_size, sizeof(elem_size), "elem_size");
    klee_assume(elem_size >= 1);
    // allow upto 1<<28 bytes per element to enable overflow with big counts
    klee_assume(elem_size <= (1 << 28));

    int new_size;
    klee_make_symbolic(&new_size, sizeof(new_size), "new_size");
    klee_assume(new_size >= 0);
    // Let new_size be large enough to overflow int when multiplied by elem_size
    klee_assume(new_size <= (1 << 30));

    int ret = grow_array(&arr, elem_size, &cur_size, new_size);

    // If grow succeeded and new_size > 0, try to touch the last byte of the logical array
    if (ret == 0 && arr && new_size > 0) {
        // Compute the intended logical size in size_t. If grow_array suffered int overflow,
        // this access may go out-of-bounds.
        size_t logical_bytes = (size_t)new_size * (size_t)elem_size;
        volatile unsigned char *p = (unsigned char *)arr;
        // Avoid zero-size
        if (logical_bytes > 0) {
            p[logical_bytes - 1] = (unsigned char)new_size;
        }
    }

    free(arr);
    return 0;
}

