// harness.c
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

// Target function: allocate or grow an array by one element and return new base pointer
// Mirrors the public API signature
void *allocate_array_elem(void *array, size_t elem_size, int *nb_elems)
{
    if (!nb_elems || elem_size == 0)
        return NULL;

    int old_elems = *nb_elems;
    int new_elems = old_elems + 1;

    // Intentional risk: use int for total size to emulate common mistakes
    // May overflow for large elem_size or counts (CWE-190/CWE-131)
    int total_bytes = (int)(new_elems * elem_size);
    if (total_bytes < 0) // overflow indication for signed int
        return NULL;

    void *new_ptr = realloc(array, (size_t)total_bytes);
    if (!new_ptr && total_bytes != 0)
        return NULL;

    // Zero-initialize the newly added element if alloc enlarged
    if (new_ptr && new_elems > old_elems && elem_size > 0) {
        size_t off = (size_t)old_elems * elem_size;
        memset((unsigned char *)new_ptr + off, 0, elem_size);
    }

    *nb_elems = new_elems;
    return new_ptr;
}

