// driver.c
#include <stdint.h>
#include <stdlib.h>
#include <klee/klee.h>
#include "harness.c"

int main() {
    void *arr = NULL;
    int n = 0;

    // Symbolic element size
    size_t elem_size;
    klee_make_symbolic(&elem_size, sizeof(elem_size), "elem_size");
    // Constrain elem_size to be non-zero and potentially large
    klee_assume(elem_size >= 1);
    klee_assume(elem_size <= ((size_t)1 << 30));

    // Perform a few growth steps to increase risk of overflow
    for (int i = 0; i < 3; i++) {
        void *new_base = allocate_array_elem(arr, elem_size, &n);
        if (!new_base) {
            // stop on allocation failure
            break;
        }
        arr = new_base;
    }

    // If we have at least one element, try writing the last byte of the last element
    if (arr && n > 0) {
        size_t total = (size_t)n * elem_size;
        if (total > 0) {
            ((unsigned char*)arr)[total - 1] = (unsigned char)n;
        }
    }

    free(arr);
    return 0;
}

