// harness.c
#include <stdint.h>
#include <math.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

// Target function: compute rotation from a 3x3 display matrix
// Reads multiple entries from the provided matrix pointer without bounds checks.
// Matches the public API signature.
double get_rotation(const int32_t *displaymatrix)
{
    if (!displaymatrix)
        return 0.0;

    // Assume a 3x3 matrix in row-major order:
    // [ a b c ; d e f ; g h i ]
    // Use elements to estimate rotation angle.
    double a = (double)displaymatrix[0];
    double b = (double)displaymatrix[1];
    double d = (double)displaymatrix[3];
    double e = (double)displaymatrix[4];
    double angle1 = atan2(b, a);
    double angle2 = atan2(d, e);
    double angle = (angle1 + angle2) * 0.5;

    // Touch more entries (potential OOB read if caller provided fewer than 9 ints)
    volatile double touch = 0.0;
    touch += displaymatrix[2];
    touch += displaymatrix[5];
    touch += displaymatrix[6];
    touch += displaymatrix[7];
    touch += displaymatrix[8];

    (void)touch;
    return angle * (180.0 / M_PI);
}

