// Target function: simple alphanumeric check (public API)
int cmdutils_isalnum(char c)
{
    unsigned char uc = (unsigned char)c;
    if ((uc >= '0' && uc <= '9') || (uc >= 'A' && uc <= 'Z') || (uc >= 'a' && uc <= 'z'))
        return 1;
    return 0;
}

